fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
pub(crate) const IDENTITY_BLOCK_BYTES:usize=64;
pub(crate) fn identity_pair_bytes(length:usize,offset:usize)->usize{length.saturating_sub(offset).min(IDENTITY_BLOCK_BYTES)*2}
pub(crate) fn compare_identity_block(left:&str,right:&str,offset:&mut usize)->Result<(bool,usize),ValueError>{
 if left.len()!=right.len()||*offset>left.len(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original child identity bounds differ"))}
 let end=left.len().min(offset.saturating_add(IDENTITY_BLOCK_BYTES));let copied=(end-*offset)*2;
 if left.as_bytes()[*offset..end]!=right.as_bytes()[*offset..end]{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original child identity bytes differ").with_retained_progress(semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:copied,..Default::default()}))}
 *offset=end;let done=end==left.len();if done{*offset=0}Ok((done,copied))
}

