 fn advance<S>(&mut self,parent:ChildAdmissionSource<'_>,lender:&'static dyn ChildReadReferenceLenderV1,ordinal:usize,read:&ChildEditorRead<'_,S>,capability:&'static ChildReadCapability,effect:&mut RetainedAllocationEffect<'_>)->Result<ChildReadAdvance,ValueError>{let g=effect.grant();let d=match self.next_demand(parent,lender,ordinal,read,capability){Ok(d)=>d,Err(error)=>{pay_work(effect,1)?;return Err(error)}};if !retained_clone_grant_admits(g,d){return Ok(ChildReadAdvance{progress:Default::default(),stamp:None})}let current=read.member_metadata();let mut child=Self::child(g);child.maximum_copy_bytes=child.maximum_copy_bytes.saturating_sub(self.comparison_bytes(current));if self.phase==Phase::Bind{let turn=parent.bind(&mut self.binding,&mut effect.nested(child));let p=turn.result.map_err(Self::failure)?.unwrap_or_default();self.lender=Some(lender);self.ordinal=ordinal;self.parent=current.parent_identity;self.child=current.child_identity;self.capability=capability as*const _ as usize;self.parent_revision=*current.parent_revision;self.child_revision=*current.child_revision;self.phase=Phase::Reference;return Ok(ChildReadAdvance{progress:Self::paid(p),stamp:None})}let boundary=effect.performed_boundary();let turn=lender.read(parent,ordinal,child);pay_work(effect,turn.work)?;let step=turn.result.map_err(Self::failure)?;let mut p=Self::paid(step.progress);if !step.progress.fits(child){return Err(refusal("Original reference lender receipt exceeds its grant").with_retained_progress(p))}if !step.done{return Ok(ChildReadAdvance{progress:p,stamp:None})}let reference=step.reference.ok_or_else(||refusal("Original parent has no requested child reference").with_retained_progress(p))?;if reference.parent_identity!=current.parent_identity||reference.parent_identity!=parent.reference_identity().2||reference.identity==0||self.reference!=0&&self.reference!=reference.identity{return Err(refusal("Original parent or member reference changed").with_retained_progress(p))}self.reference=reference.identity;if effect.performed_since(boundary)?==0{pay_work(effect,1)?}
 let accepted=match self.phase{Phase::Reference=>{let same=self.compare(reference.text(self.field),Self::current_text(current,self.field),&mut p)?;if same{self.field+=1;if self.field==7{self.phase=Phase::Capability;self.field=0}}false},Phase::Capability=>{let (left,right)=match self.field{0=>(current.artifact_kind,capability.artifact_kind),1=>(current.standard,capability.standard),_=>(current.subset,capability.subset)};if self.compare(left,right,&mut p)?{self.field+=1;if self.field==3{self.phase=Phase::Ready}}false},Phase::Ready=>true,_=>unreachable!()};Ok(ChildReadAdvance{progress:p,stamp:accepted.then(||ChildReadStamp{original:parent.reference_identity(),ordinal:self.ordinal,reference:self.reference,parent:self.parent,child:self.child,capability:self.capability,parent_revision:self.parent_revision,child_revision:self.child_revision})})}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.phase==Phase::Closed{return Ok(Default::default())}if self.binding.is_some(){Self::nested(RetainedCloneBinding::close_demand(&self.binding,body.saturating_sub(Self::HEADER))?)}else{Ok(Self::birth_demand())}}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if self.phase==Phase::Closed{return Ok(0)}if self.binding.is_some(){RetainedCloneBinding::close_work_demand(&self.binding,body.saturating_sub(Self::HEADER))}else{Ok(1)}}
 pub fn close_step(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>)->Result<RetainedCloneStep,RetirementPollExit>{let g=effect.grant();if !self.closing{pay_work(effect,1)?;return Err(refusal("Original child read qualification closure has not begun").into())}if self.phase==Phase::Closed{return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demand(body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.binding.is_some(){let step=RetirementPollExit::resume(RetainedCloneBinding::close_one(&mut self.binding,body.saturating_sub(Self::HEADER),&mut effect.nested(Self::child(g))))?;return Ok(RetainedCloneStep::Progress(Self::paid(step.progress())))}pay_work(effect,1)?;self.lender=None;self.phase=Phase::Closed;Ok(RetainedCloneStep::Complete(Self::paid(Default::default())))}
